RSNA = ['RSNA Exhibition Services Office','RSNA Career Connect','Radiology Reimagined','AI Theater','Innovation Theater','Industry Expert Theater','Bark Park','Golf Park','Recharge Park']
def classify(name):
    n=name
    if n in RSNA: return 'RSNA-run space / feature'
    if n in MEDIA: return 'Media / Publisher'
    if n in STAFF: return 'Staffing / Recruiting / Locums'
    if n in TELE: return 'Teleradiology / Radiology Practice / Imaging Center'
    for seg,names in OVR.items():
        if n in names: return seg
    l=n.lower()
    if re.search(r'society|college|association|board of|registry|alliance|coalition|commission|council|federation|academy of|ismrm|spie|seram|cadi|rad-aid|aawr|ahra|foundation|intersocietal|image gently|kmdia|physicists|architects|nma|cbr\)|japan radiological|chinese society|colombian|sociedad|italian society|french society|royal college|pavilion|institute of radiology',l):
        return 'Society / Association / Non-profit'
    if re.search(r'health|clinic|hospital|medicine|medical center|university|kaiser|mayo|sutter|cedars|geisinger|ochsner|advocate|essentia|baylor|endeavor|jefferson|loyola|penn state|piedmont|prisma|rwjbarnabas|sanford|virtua|vanderbilt|uva|upmc|ucla|ucsf|uc davis|uc irvine|ut southwestern|stanford|johns hopkins|mallinckrodt|roswell|scottish rite|seattle children|veterans|billings|bassett|carilion|alaska native|vancouver island|wvu|hca|commonspirit|cork|miami',l):
        return 'Health System / Academic Dept (recruiting)'
    if re.search(r'\bai\b|\.ai|intelligence|deep|neural|learning',l): return 'AI / Machine Learning'
    if re.search(r'pacs|dicom|informatics|software|cloud|workflow|imaging solutions',l): return 'Imaging IT / PACS / Workflow / Reporting'
    if re.search(r'ultrasound|x-ray|xray|mri|ct |medical systems|medical equipment|medical imaging',l): return 'OEM - Modality/Equipment'
    return 'Other / Services (review)'

